#Requires -Version 7.0
[CmdletBinding()]
param([Parameter(Mandatory)][string]$Id,[switch]$Preview,[switch]$BuildOnly,[ValidateSet('auto_source','open','half_open','closed','profile','not_visible')][string]$SourceEyeState='auto_source',[string]$PoseGuide,[string]$ContinuityReference,[int[]]$PreviousHeadCrop)
$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot
$base=Join-Path $root 'art\full_character_redraw_1080p_v01'
$plan=Get-Content -LiteralPath (Join-Path $base 'REDRAW_PLAN.json') -Raw | ConvertFrom-Json
$job=$plan.jobs | Where-Object id -eq $Id
if(-not $job){throw 'Unknown drawing ID.'}
$renderReference=if($job.production_reference){$job.production_reference}else{$job}
$outputSize=$renderReference.output_size
$outputSizeString=$renderReference.output_size_string
$run=Join-Path $base $job.run_relative
if(Test-Path -LiteralPath (Join-Path $run 'attempt.json')){throw 'Attempt already recorded. Do not retry automatically.'}
$sourceGuide=Join-Path $run 'inputs\source_pose_guide.png'
if($PoseGuide){
 $sourceGuide=(Resolve-Path -LiteralPath $PoseGuide).Path
 [IO.File]::WriteAllText((Join-Path $run 'SOURCE_GUIDE_CHOICE.json'),(@{guide=$sourceGuide;basis='Explicit clean visible-equivalent source guide; preserve original nominal source and evidence alongside it.'}|ConvertTo-Json),[Text.UTF8Encoding]::new($false))
}
$eyeFile=Join-Path $base 'inputs\eye_G02-01_F100.png'
$eyeGuideRule="REFERENCE 4 is EYES ONLY, the user-preferred G02-01 / F100 economical black upper lash and eye construction. Use ONE SOLID DARK-CHARCOAL IRIS FILL with small white glints, without multiple bands or gradients. Do not copy its half-lidded state universally: current source 1 controls eye opening, expression and gaze. This eye-only crop never determines drill size."
if($SourceEyeState -in @('open','closed','profile','not_visible')){
 $openMaster=Join-Path $base 'inputs\eye_open_mono_master.png'
 $eyeFile=if($SourceEyeState -eq 'open' -and (Test-Path -LiteralPath $openMaster)){$openMaster}else{$sourceGuide}
 $eyeGuideRule="REFERENCE 4 anchors the CURRENT SOURCE EYE STATE: $SourceEyeState. The source 1 expression must be preserved. Draw single-color dark-charcoal irises with small white glints when visible, and economical G02-like upper-lash ink, but NEVER flatten an OPEN source eye into the G02 half-lidded state. Do not add eyes to a closed-eye, back, mouth-only or hand-only crop. Reference 3's closed eyes are irrelevant to an open current source."
}
$hairReference=Join-Path $base 'inputs\identity_full_drill_three_views.png'
& (Join-Path $PSScriptRoot 'Prepare-CleanFaceStyleReference.ps1') | Out-Null
$faceReference=Join-Path $base 'inputs\PV_face_style_no_headgear.png'
if($job.group -in @('G06','G07','G19','G37','G38','G39','G40')){
 & (Join-Path $PSScriptRoot 'Prepare-InvertedIdentityRefs.ps1')
 $hairReference=Join-Path $base 'inputs\identity_full_drill_three_views_rot180.png'
 $faceReference=Join-Path $base 'inputs\PV_face_style_no_headgear_rot180.png'
 if($eyeFile -ne $sourceGuide){$eyeFile=Join-Path (Split-Path -Parent $eyeFile) ([IO.Path]::GetFileNameWithoutExtension($eyeFile)+'_rot180.png')}
}
$images=@($sourceGuide,$hairReference,$faceReference,$eyeFile)
[IO.File]::WriteAllText((Join-Path $run 'SOURCE_EYE_STATE.json'),(@{source_eye_state=$SourceEyeState;eye_reference=$eyeFile;basis='State declared from actual source inspection; not inferred from another generated face.'} | ConvertTo-Json),[Text.UTF8Encoding]::new($false))
$defaults=Get-Content -LiteralPath (Join-Path $root 'image_defaults.json') -Raw | ConvertFrom-Json
$registryPath=Join-Path $base 'ASSET_REGISTRY.json'
$registry=if(Test-Path -LiteralPath $registryPath){Get-Content -LiteralPath $registryPath -Raw | ConvertFrom-Json -AsHashtable}else{@{}}
$neighbor=''
if($ContinuityReference -and $job.previous_in_family){throw 'Use the reviewed previous-in-family reference when one exists.'}
if($ContinuityReference){
 $continuityPath=(Resolve-Path -LiteralPath $ContinuityReference).Path
 $continuityRun=Split-Path -Parent $continuityPath
 $continuityReview=Get-Content -LiteralPath (Join-Path $continuityRun 'VISUAL_REVIEW.json') -Raw | ConvertFrom-Json
 if(-not $continuityReview.continue_family -or -not $continuityReview.primary_static_pass -or -not $continuityReview.independent_static_pass){throw 'Explicit continuity reference must have actual primary and independent visual review.'}
 $images+=$continuityPath
 $neighbor='REFERENCE 5 is a separately reviewed related-shot continuity drawing. It controls only substantial drill width/length, continuous coil construction, bead attachment, gray/mint palette and natural shoulder overlap. CURRENT reference 1 controls the pose, crop, clothing, gaze and eyelid opening. Do not copy reference 5 eye opening or shorten its large drill into a tiny tip.'
 [IO.File]::WriteAllText((Join-Path $run 'EXPLICIT_CONTINUITY_REFERENCE.json'),(@{image=$continuityPath;visual_review=(Join-Path $continuityRun 'VISUAL_REVIEW.json');scope='Hair construction, scale, palette and overlap only; current source controls expression/pose.'}|ConvertTo-Json),[Text.UTF8Encoding]::new($false))
}
if($job.previous_in_family){
 $prev=$plan.jobs | Where-Object id -eq $job.previous_in_family
 if(-not $registry.ContainsKey($prev.id) -or -not $registry[$prev.id].primary_static_pass -or -not $registry[$prev.id].independent_static_pass){throw 'Preceding drawing requires both current primary and independent visual review; do not propagate a legacy or unreviewed master.'}
 $prevRun=Join-Path $base $prev.run_relative
 if($registry.ContainsKey($prev.id) -and $registry[$prev.id].primary_static_pass -and $registry[$prev.id].independent_static_pass){$prevRun=$registry[$prev.id].selected_run}
 $reviewPath=Join-Path $prevRun 'VISUAL_REVIEW.json'
 if(-not(Test-Path -LiteralPath $reviewPath)){throw 'Preceding cel requires actual visual review before continuing this group.'}
 $review=Get-Content -LiteralPath $reviewPath -Raw | ConvertFrom-Json
 if(-not $review.continue_family){throw 'Preceding cel is on hold; do not propagate its defects.'}
 Add-Type -AssemblyName System.Drawing
 $previous=[Drawing.Bitmap]::new((Join-Path $prevRun 'qa_white.png'))
 try{
  $closeCrop=$outputSize[0]/[double]$outputSize[1] -gt 0.95
  $portion=if($closeCrop){1.0}elseif($job.kind -eq 'body_pose'){0.42}else{0.85}
  $height=[int][Math]::Ceiling($previous.Height*$portion)
  $y=if($job.group -in @('G06','G07','G19','G37','G38','G39','G40')){$previous.Height-$height}else{0}
  $headBox=if($PreviousHeadCrop){
   if($PreviousHeadCrop.Count -ne 4 -or $PreviousHeadCrop[0] -lt 0 -or $PreviousHeadCrop[1] -lt 0 -or $PreviousHeadCrop[2] -le 0 -or $PreviousHeadCrop[3] -le 0 -or ($PreviousHeadCrop[0]+$PreviousHeadCrop[2]) -gt $previous.Width -or ($PreviousHeadCrop[1]+$PreviousHeadCrop[3]) -gt $previous.Height){throw 'Previous head crop must be an actually inspected rectangle inside the reviewed neighbor QA.'}
   [Drawing.Rectangle]::new($PreviousHeadCrop[0],$PreviousHeadCrop[1],$PreviousHeadCrop[2],$PreviousHeadCrop[3])
  }else{[Drawing.Rectangle]::new(0,$y,$previous.Width,$height)}
  $head=$previous.Clone($headBox,[Drawing.Imaging.PixelFormat]::Format32bppArgb)
  $neighborPath=Join-Path $run 'inputs\previous_head_continuity.png'
  try{$head.Save($neighborPath,[Drawing.Imaging.ImageFormat]::Png)}finally{$head.Dispose()}
  if($PreviousHeadCrop){[IO.File]::WriteAllText((Join-Path $run 'PREVIOUS_HEAD_CROP.json'),(@{source=(Join-Path $prevRun 'qa_white.png');source_sha256=(Get-FileHash -LiteralPath (Join-Path $prevRun 'qa_white.png')).Hash.ToLowerInvariant();crop_xywh=$PreviousHeadCrop;purpose='Read-only continuity reference crop to exclude prior arm/hand action; CURRENT original guide controls pose and expression.';not_artwork_edit=$true}|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))}
 }finally{$previous.Dispose()}
 if($job.group -eq 'G45'){
  # Preserve the independently reviewed negative space as real alpha. A white
  # head/body composite alone is ambiguous when the original source holds a prop.
  $approvedAlpha=[IO.Path]::GetFullPath($registry[$prev.id].image)
  if((Get-FileHash -LiteralPath $approvedAlpha).Hash.ToLowerInvariant() -ne $registry[$prev.id].sha256){throw 'Approved occlusion reference hash changed; inspect it again.'}
  $neighborPath=Join-Path $run 'inputs\previous_visible_alpha_continuity.png'
  Copy-Item -LiteralPath $approvedAlpha -Destination $neighborPath -Force
  [IO.File]::WriteAllText((Join-Path $run 'PREVIOUS_VISIBLE_ALPHA_REFERENCE.json'),(@{source=$approvedAlpha;sha256=$registry[$prev.id].sha256;review=$reviewPath;purpose='Prop-free visible-character alpha / collar / grip / complete-drill continuity only. Current source controls new hand, sleeve, skirt and ribbon ink.';not_artwork_edit=$true}|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))
 }
 $images+=$neighborPath
 $neighbor=@'
REFERENCE 5 is a HEAD-REGION continuity crop of the preceding reviewed generated cel in this action group. Preserve its hair construction, bead root, braid length, coil direction, palette and ink density. It does not control the current body pose or expression, which come from CURRENT original reference 1. The user's original substantial drill-lock size overrides any tiny thin drill in an older candidate. Maintain sensible evolving occlusion without side flips, shortened coils, missing middle turns or arbitrary shoulder crossing.
'@
 if($job.group -eq 'G45'){$neighbor='REFERENCE 5 is the preceding independently reviewed PROP-FREE visible character with its REAL TRANSPARENT basket/bread occlusion hole. Preserve its substantial complete drill, bead attachment, little BLACK stand collar below the visible neck, narrow RED clothing strip beside the original bread, and single foreground gripping-hand construction. Its transparent central space is intentional: do not fill it with hidden chest, full red bow, belly, second hand, basket or bread. CURRENT original reference 1 controls the new skirt/sleeve/ruffle/ribbon and visible hand ink, not a frozen copy of reference 5. No cyan annotation or placeholder is part of this reference.'}
}
$framing=switch($job.kind){
 'body_pose' {'Preserve the source full-body or seated pose and the exact source cropping. Include only the visible source character extent; do not invent legs if the source cuts them off.'}
 'half_body' {'This is a half-body/cropped-body animation cel. Preserve the source crop boundary, arm and hand gestures, eye expression and body tilt. Do not expand it into a full-body standing pose.'}
 'head_detail' {'This is a HEAD / closely cropped face cel. Preserve the source expression, eye opening, mouth, head angle and crop boundaries. Draw only this character region, not a whole figure or a framed card.'}
 'hand_detail' {'This is a HAND / wrist / sleeve detail cel. Copy the source hand pose, finger count, contact points and sleeve shape. Do not add a head, figure, table, gift box, room, lettering or effects.'}
 'mouth_detail' {'This is the LOWER FACE / MOUTH detail seen through the source horizontal crop. Preserve that source mouth opening and jaw/neck relationship. Only draw the source-visible lower face, hair ends and collar; no eyes, complete head, figure, white frame or background strip.'}
}
if($job.group -eq 'BROOCH'){$framing='Draw only the small portrait face and hair from inside the oval accessory, adapted to the new character. Do not draw the metal rim, red bow, gold halftone overlay, room or lettering. Preserve the source face direction and simple expression.'}
if($job.group -eq 'G47'){$framing+=' The guide isolates exactly ONE original head card, even though several copies appear in the final source scene. Draw only ONE source-visible head, neck, RED standing costume collar and tiny white shoulder points inside that viewport. No repeated heads, card, white rectangle, border, text or petals. Preserve the current top/bottom viewport cut: do not invent hidden chest or complete the cap beyond the source card. Keep the source RED collar; do not import a black high collar or red neck bow from the earlier black-maid shots. The correctly scaled single gray/mint drill may continue out through the bottom crop, rather than shrinking to show its tip. Scene duplicates will reuse this one asset through separate source-instance registration.'}
if($job.group -eq 'G50'){$framing+=' This late-source costume differs from the earlier black-collar/red-bow maid: preserve the CURRENT RED standing neck collar, large BLACK chest bow with gold clasp, black/white/red shoulder panels and source white frills. Preserve the raised BLACK GLOVE on image right, its complete palm-up fingers and the BARE peach forearm leaving the bottom crop. Do not turn that glove into a bare hand, add a white wrist cuff/long black sleeve, swap bow/collar colors, or cut off fingertips that are visible in the original. Draw only the currently visible close-up extent, with the existing top-of-cap and bottom-of-forearm crop. No lettering or petals.'}
if($job.group -eq 'G23'){$framing+=' The broom, wooden shaft and straw are an independent prop. Draw NO broom and NO wooden pole. Preserve both source hand silhouettes and exact finger grasp around the future pole; leave the pole space transparent for later original-prop compositing.'}
if($job.group -in @('G24','G25')){$framing+=' The white duck with its orange beak is a separate original foreground animal/prop layer. Do not draw the duck, bird, beak or feathers. Preserve the source-visible human hands and fingertips at their original positions around that duck, leaving transparent space for its later original-layer composition. Do not invent palm/body regions completely hidden by the duck. G25 has spread open arms, not a broom grasp; keep that exact source pose.'}
if($job.group -in @('G23','G24','G25')){$framing+=' The source WHITE MAID HEADBAND and attached BLACK DOUBLE-LEAF ornament are visibly present and MUST remain on the new gray-haired head. They are part of the source costume, not removable background props. Keep them seated naturally against the bob, with no floating gap.'}
if($job.group -in @('G06','G07')){$framing+=' The large pale ROUND DISC is a separate foreground prop, not clothing or part of the character. Do not draw that circle/disc in this character layer. Leave its area transparent except for the character hands/fingers that visibly overlap it. Preserve the source-visible disconnected head, limbs and fingers around this occlusion; do not invent a torso hidden by the disc. Preserve the original gray casual garment and bare feet, with no maid headband or apron.'}
if($job.group -in @('G06','G07')){$framing+=' The current head is UPSIDE DOWN. Identity references 2 and 3 were technically rotated 180 degrees to match this camera roll. The anatomical LEFT bead/lock root therefore belongs on IMAGE LEFT of this upside-down head, not image right. Do not mirror the character. The single corkscrew may swing naturally with gravity/current pose; the reference roll anchors the anatomical attachment, not a rigid world-space curl direction.'}
if($job.group -eq 'G19'){$framing+=' This is the original UPSIDE-DOWN DIAGONAL maid close-up, with the head below the hands and the body leaving the upper-right crop. Identity/style/eye references have a technical 180-degree roll to help preserve anatomical left; CURRENT source controls the remaining diagonal tilt. Do not turn her upright or mirror her. Preserve the original white maid cap and attached black double-leaf ornament, black sleeves, white cuffs and shoulder ruffles, and red CLOTHING bow. The orange baguette/bread is an independent foreground prop: draw NO bread, loaf or orange oval. Preserve only the source-visible fingers and human regions around it, with genuine transparent space for later original-bread composition; do not reconstruct a body or palms completely hidden by that bread.'}
if($job.group -in @('G37','G38','G39','G40')){$framing+=' This CURRENT maid dance drawing is UPSIDE DOWN, with the head near the bottom and the skirt/torso leaving the TOP crop. The source is not a standing full-body view: preserve exactly its on-canvas visible half-body and current hand gesture, and draw no invented hidden legs, feet or shoes above the frame. References 2/3/4 have a technical 180-degree roll; keep the anatomical LEFT bead-and-single-drill root on the corresponding IMAGE LEFT side of the inverted head, with natural turning/occlusion and no mirror. Preserve the source white maid cap and its exactly two attached black leaves, black long sleeves, white cuffs/shoulder ruffles/apron, and red clothing bow. No round disc, bread, case or generic casual outfit. Preserve CURRENT eye openness: G40 has CLOSED eyes, while G37/G38/G39 retain their own open gaze. The paired drawings in each group contain actual different sleeve, bow, belt and apron lines, so preserve the CURRENT source body ink rather than freezing or copying the previous drawing whole.'}
if($job.group -eq 'G27'){$framing+=' The person is seated in bed in a loose gray/lavender wide-neck short-sleeved T-shirt, with her anatomical RIGHT hand (viewer left) visibly resting over the foreground blanket edge. Preserve that source-visible hand, the short sleeves and the small visible opposite forearm. Bed, blanket, pillows, headboard and room are separate layers and must be transparent here. The blanket hides the lower torso and legs completely: draw no lower body, invented second hand, bedding or bed-shaped white/gray silhouette. Keep the exact source foreground occlusion boundary; do not turn this into a full sitting figure. There is NO maid cap, black leaf, apron, white cuff, red bow or school uniform in this casual source.'}
if($job.group -eq 'G26'){$framing+=' This is an EXTREME frontal face close-up: preserve the original large eye/face positions and wide open worried gaze at the original on-canvas scale. The top of the head and the sides are genuinely cut off by the camera. Do not shrink the head into a complete floating portrait or fit the entire hairstyle/spiral into the frame. Draw only the naturally visible portions of the new short bob and substantial drill; its anatomical-left bead/root may approach the viewer-right crop, and its lower turns may leave the frame. Keep the tiny original gray casual neckline at the bottom where visible, with no maid headband, black leaf, apron, red neck bow or school outfit. Remove the source lyric rectangle and all black scratch/wipe effects; those masks will be composited separately.'}
if($job.group -in @('G28','G29')){$framing+=' The large PINK OPEN CASE held against the face/chest is a separate foreground prop, not skin, hair or costume. Do NOT draw the case, its lid, fittings or handles. Leave its occluded area genuinely transparent; preserve only source-visible human regions outside its boundary and any visible fingertips gripping its edges. The source MOUTH, chin, neck and central upper torso are hidden by the case: do not invent these hidden parts or reveal a mouth below the nose. Replace ALL original long red hair with the requested short ash-gray bob and single substantial gray/mint drill; natural portions of the new drill may remain hidden behind the case. No maid cap, black leaf ornament, apron, cuffs, high collar or red neck bow in this casual shot.'}
if($job.group -eq 'G11'){$framing+=' This is the casual FACE AND BARE HAND close-up. Preserve the CURRENT source eyelid openness, brow pressure, exact mouth state and relative hand-to-cheek height; do not copy the preceding drawing open mouth or eye shape. Orange splashes/rays and lettering are independent foreground effects, not hair, fingers, skin or clothing. Remove them from the artwork; preserve the human regions actually visible around them without inventing a whole hidden wrist, arm, shoulder or lower body. Keep the naturally cropped ash-gray bob, connected substantial drill, bare neck and original visible curled fingers. No maid cap/headband, leaf ornament, high collar, neck bow or white cuff in this casual source.'}
if($job.group -eq 'G28'){$framing+=' Preserve the source front-facing gray loose short-sleeved T-shirt with its asymmetric hem and BLACK DRAWSTRING SHORTS, both bent bare arms and visible gripping fingers. The original camera cuts the thighs at the bottom: do not invent full legs, feet, shoes or a standing turnaround pose. Keep the large case-shaped occlusion opening through the middle instead of filling it with invented shirt or anatomy.'}
if($job.group -eq 'G29'){$framing+=' This is the CURRENT independently redrawn CLOSE-UP, not a full body. Draw only the source-visible upper face with both open eyes and ash-gray bob, and small genuinely visible side fragments above/around the pink case. Preserve the original large head scale and crop; no invented hands, shoulders, mouth or body below the case. Drill volume remains substantial where visible, without forcing a full small curl to fit inside the crop.'}
if($job.group -eq 'G17'){$framing+=' This CURRENT figure is BACK-FACING with the head looking back toward camera. Preserve the broad BACK waist bow and the two crossed WHITE BACK apron straps. Do NOT turn the torso into a front view or put the large front apron bib over the back. Keep the source left spread hand and right curled fingers holding the future bucket handle, with both bent legs/black ankle-strap shoes in the original flying pose. The bucket and handle are independent props and must be absent, retaining only visible finger contours. Use only the original source sparse flat PV line/color method; do not inherit polished gray iris rings, shiny bob streaks or complex dress shading from an older generated F1501. Visible eyes have ONE solid dark-charcoal iris with a small white glint, no separate pupil/ring/lower gray band. The maid-cap ornament has two leaves with a short shared root and NO additional pointed tail hanging down from that root.'}
if($job.group -eq 'G35'){$framing+=' This is the CURRENT front-facing maid seated on the independent CHAIR. Preserve the small waist/lap hand gesture, bent seated hip and skirt folds, two visible lower legs and black ankle-strap shoes. Do not replace this with standing, crossing legs, a generic turnaround or the neighboring side view. The chair, armrests and backrest are separate props: leave them transparent, without completing any person part fully hidden by them. Keep the source cap and exactly two attached black leaves.'}
if($job.group -eq 'G45'){$framing+=' This is the CURRENT reclining/floating maid holding the independent BASKET OF BREAD against her chest. Preserve her tilted torso, raised skirt/knees, both bent bare lower legs with black ankle straps/shoes, current sleeve/cuff and white shoulder-ruffle shapes, white apron draped over the raised lap and the CURRENT long back-bow ribbons. The three source states differ in actual skirt/sleeve/white ribbon/ruffle ink: preserve the CURRENT drawing rather than freezing the previous body. Basket, wicker, handles and every orange bread loaf are separate props and must be absent from this transparent character layer. Preserve only source-visible human hands/fingertips around the basket edge, never invent a second palm, chest or hidden arm behind it. Keep the cap and two attached black leaves, current smile/open gaze and source-visible red clothing; do not change this into standing, a chair pose or a generic front maid turnaround. Stars, sparkles and captions are separate effects and must be omitted.'}
if($job.group -eq 'G21' -and $SourceEyeState -eq 'not_visible'){$framing+=' This is one of the FIRST TWO actual rear/side-back turning drawings. Preserve the current source rear-facing head rotation and the narrow face/cheek sliver hidden by bangs: there is NO visible eye in this source state. Do not turn the face further toward camera, expose a profile eye, add a lash, or copy an eye from any identity/neighbor reference. The next source turning states reveal eyes later. Keep the substantial gray/mint drill attached continuously below the anatomical left ear with the current source head roll; current pose and actual hair occlusion control visibility.'}
$prompt=@"
EDIT reference 1 into ONE transparent-background CHARACTER ANIMATION CEL for source drawing $Id. Preserve the ORIGINAL BODY ART, clothing outlines, arms, fingers, legs, knees and shoes, at their existing pixel positions. Change the head/face/hair to the new identity and match exposed skin to warm peach. Preserve the body's original ink paths rather than inventing a fresh standing or walking pose. Return the complete character region as one coherent transparent cel; do not return just a head. The first reference is already prepared on the desired output canvas: preserve its pose placement and framing, do not recenter, zoom, mirror or change the view. Transparent clear space outside the character. Do not draw checkerboard pixels, shadows around or below the character, scene props, typography, cards, petals, stars, rings, lamps, chairs, borders, watermarks or any background. Also leave independent held objects out: no cup, teapot, box, gift box, basket, round disc or table. Keep the visible fingers and original grasp/contact pose, with transparent space for those original objects to be composited later. Captions, props, effects and background will be composited separately in 1920x1080 post-production.

$framing

REFERENCE 1: CURRENT ORIGINAL PV pose, source expression and eye openness, clothing, proportions, shoulder width, hand gestures and economical ink method. It controls the current action. Eye rendering comes from reference 4, while current eyelid opening and gaze still follow reference 1. Captions, effect occlusion and background must be left out; reasonably complete only small obscured character areas.
REFERENCE 2: ORIGINAL identity front / profile / rear HEAD AND COMPLETE DRILL construction, left to right. The lower extent intentionally includes the full front/profile corkscrew rather than cutting off its tip. Use the view matching CURRENT source 1. Rounded short silver/ash-gray bob, soft bangs, healthy light warm peach skin, TWO red beads and ONE long gray/mint tapering corkscrew on anatomical LEFT. REPLACE THE ENTIRE ORIGINAL RED HAIRSTYLE, including BOTH old red side-drills, their black triangular insets and every red nape/fringe sliver. Do not leave the original red twin tails behind the new bob or add the new single drill to those old twins. Empty space vacated by the old hairstyle is transparent. The only red in the new HAIR identity is the two round beads; original source RED CLOTHING such as the neck bow remains red and is not hair. Preserve a source-visible white cap and attached black double-leaf ornament, which are costume, rather than old red hair or its black insets. In an upright REAR view its root is IMAGE LEFT; never keep front-view image-right placement when turning away. Identity and hair dimensions only: IGNORE every bit of school collar, tie, vest or armband at its lower crop edge. Do not copy polished shading or mint reflective bands on the bob.
REFERENCE 3: flat PV FACE-ONLY drawing method. Use its grouped ash-gray bob contours and economical flat-color rendering, not its closed eyes. Current eyes come from source openness plus reference 4. This face-only crop does not determine drill size. All clothes, source-visible maid headband/black-leaf ornament, and pose come from CURRENT source 1; preserve those source headgear pieces when visible even though the school identity lacks them.
$eyeGuideRule
ABSOLUTE COSTUME LOCK: Reference 1 is the only clothing reference. Keep each original garment's shape and color. A gray loose casual top remains a gray loose casual top, bare feet remain bare, a red costume remains red, and black maid uniform remains black maid uniform. Do not automatically add a maid outfit, apron, neck bow, high collar, cuffs, headband or shoes to a casual / barefoot source. Do not copy clothing from any other reference. When the current source shows the maid cap and its black double-leaf ornament, preserve EXACTLY TWO pointed black leaves sharing one base, with the same source visibility and orientation; never add a third projecting blade. Do not expose hidden tips or invent headgear in casual or cropped sources.
$neighbor

DRILL VOLUME: The largest turns should preserve the substantial width, mass and full tapering construction actually visible in the original front/profile identity reference. VOLUME HERE MEANS CONTOUR/COIL GEOMETRY ONLY, NOT LIGHTING. Render BOTH bob and drill as the same UNLIT FLAT PV HAIR: one uniform ash-gray material fill, one uniform muted mint structural stripe color and black contour/coil-separation ink. The mint band is material color, not a reflection. NO white sheen or streak, glossy highlight, specular spot, gradient, rim light, glow, airbrushed shading, dark volume panels or shaded underside on the drill. Ignore ALL lighting and reflected streaks in the polished identity reference, on the bob AND on the drill. Do not substitute a pencil-thin little tail or impose a fixed head-width/head-height ratio. Retain a complete thick-to-thin coherent corkscrew construction and a genuinely long tapering lower part when visible. In a large head close-up the correctly scaled lock may continue past the original frame crop or behind the shoulder: do not miniaturize it just to squeeze every turn into the canvas. Preserve legitimate source cropping and occlusion. The tiny thin drill on the user's G02 eye-reference image is specifically rejected and is not a hair-size reference.

CONTINUITY: The one silver-gray/mint spiral attaches below the anatomical LEFT ear/nape at the same two red beads; for an UPRIGHT front head this means viewer right, for an UPRIGHT rear head viewer left. Rotate that anatomical layout WITH the head when it rolls or turns upside down, rather than keeping the root on a fixed image side. Its complete connected tapering middle and curled tip follow the actual full-drill identity reference, with several broad turns; do not impose an arbitrary fixed head-height ratio. It may drape naturally beside the shoulder with this pose; it need not be pulled in front of the shoulder. Maintain root, intrinsic volume, coil direction and natural evolving overlap consistently with the preceding cel. In DANCE shots the lock MUST swing, compress and rebound with the source movement and head/shoulder turn; apparent root-to-tip length and orientation may change. Never copy a rigid vertical lock or use an equal-length ratio as a replacement for observed motion. Preserve legitimate arm/shoulder occlusion: a foreground crossing forearm covers the lower lock, not vice versa. Do not lay a complete long coil over an arm merely to display its tip. A per-cel actually inspected user motion guide, when supplied, controls hair placement/elastic pose only; original reference 1 still controls exact body gesture, costume, expression and crop. Preserve legitimate source crop and occlusion rather than forcing the entire drill into a mouth/hand close-up.

DRAWING: Match ORIGINAL source 1's simplified Japanese hand-drawn PV. Sparse confident dark ink cores with small natural stroke-width changes; a few grouped hair contours, simple eye/mouth marks and economical garment folds. Flat ash-gray hair, muted mint stripe, plain red beads, warm light peach skin roughly #FCE8DC, and original outfit's solid fills. Keep fill interiors a single solid tone, with at most a small separate source-like shadow shape. No glossy bead glints, airbrush, gradients, individual fine strands, paper grain, smudging, fabric texture, dramatic lighting, cast shadow, glow or polished illustration finish. Keep new hair and original clothes at the same line density. Output only this single transparent character cel.
"@
if($job.kind -eq 'hand_detail'){
 $images=@($images[0])
 $prompt=@"
EDIT the first reference into exactly ONE isolated hand-and-visible-wrist animation cel on genuine transparent alpha. Preserve every original finger position, bend, hand outline and canvas crop; change only skin fill toward healthy light warm peach #FCE8DC and restore tiny areas hidden by caption glyphs. Copy the source's economical dark PV ink and flat skin fill. Draw ONLY the bare hand/wrist pixels visible in the source. No new sleeve or cuff beyond the source crop, no head, no hair, no clothes, no gift box, bow, brooch, jewels, sparkles, captions, borders or background. The red bow and its gold oval are a separate PROP, and must be absent from this hand layer. Keep all visible hand contours at their original pixel positions; do not recenter or redesign the gesture. This is a hand cel for later compositing over the original prop, so the untouched prop belongs in transparent empty space here. No gradients, shine, texture or cast shadow. Genuine alpha outside the hand.
"@
}
$endingPalette=$defaults.ending_costume_palette
if($endingPalette -and $job.group -in $endingPalette.scope_groups -and
   $job.source_frame -ge $endingPalette.source_frame_range[0] -and
   $job.source_frame -le $endingPalette.source_frame_range[1]){
 $paletteReference=Join-Path $root $endingPalette.clothing_only_reference
 if(-not(Test-Path -LiteralPath $paletteReference)){throw 'Selected ending clothing palette reference is missing.'}
 if((Get-FileHash -LiteralPath $paletteReference).Hash.ToLowerInvariant() -ne $endingPalette.clothing_only_reference_sha256){throw 'Selected ending clothing palette reference changed; inspect before generation.'}
 # Replace the redundant face-style input, retaining at most five references.
 # Source 1 and eye reference 4 still control the actual pose and eye method.
 $images[2]=$paletteReference
 $prompt=[regex]::Replace($prompt,'(?m)^REFERENCE 3:.*$','REFERENCE 3: USER-SELECTED ENDING CLOTHING PALETTE ONLY. Match the muted desaturated gray-green fabric with black bow, white apron/frills and gold clasp. Ignore its pose, crop, hair, lighting and body proportions; CURRENT ORIGINAL reference 1 controls these, and reference 4 controls eye method.')
 $prompt=$prompt.Replace('original source RED CLOTHING such as the neck bow remains red and is not hair.','The two red hair beads remain red. Visible ending clothing follows the explicit gray-green palette rule below.')
 $prompt=$prompt.Replace("Keep each original garment's shape and color.","Keep each original garment's shape; ending red fabric follows the selected gray-green palette below.")
 $prompt=$prompt.Replace('a red costume remains red','ending red costume fabric becomes selected gray-green')
 $prompt=$prompt.Replace('RED standing','GRAY-GREEN standing')
 $prompt=$prompt.Replace('Keep the source RED collar','Use the selected GRAY-GREEN collar')
 $prompt=$prompt.Replace('black/white/red shoulder panels','black/white/gray-green shoulder panels')
 $prompt+="`n`nEXPLICIT USER ENDING PALETTE, 2026-11-01: "+$endingPalette.rule+"`nThis overrides earlier source-red CLOTHING color wording only for this ending costume. The two RED hair beads remain RED. The user selected the palette, not another pose or generic illustration rendering.`n"
 [IO.File]::WriteAllText((Join-Path $run 'ENDING_PALETTE_REQUEST.json'),(@{policy=$endingPalette.policy_id;source_frame=$job.source_frame;reference=$paletteReference;reference_sha256=$endingPalette.clothing_only_reference_sha256;palette_user_selected=$true;whole_art_user_accepted=$false}|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))
}
[IO.File]::WriteAllText((Join-Path $run 'prompt.txt'),$prompt,[Text.UTF8Encoding]::new($false))
if($BuildOnly){[PSCustomObject]@{prompt=$prompt;images=$images;size=$outputSizeString};return}
# Base requests redraw one complete coherent visible character. A local-repair
# mask is a separate version and requires a subsequent whole-character imggen
# return before final selection; do not apply a preserve-body mask by default.
& (Join-Path $PSScriptRoot 'Invoke-ReferenceImage.ps1') -PromptFile (Join-Path $run 'prompt.txt') -InputImages $images -OutputDirectory $run -Size $outputSizeString -Quality high -Background transparent -OutputFileName 'character_api_original.png' -Stage ('Full-film GOAL: '+$Id+' coherent character, G02 single-color eye trial and substantial continuous drill') -Preview:$Preview

